<?php
declare(strict_types=1);
namespace App\Interface\Http\Review\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Review\Mapper\ReviewResponseMapper;use App\Application\Review\Service\BuildReviewSessionService;use App\Application\Review\Service\NavigateReviewSessionService;use App\Domain\Review\Enum\ReviewSessionKind;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class ReviewSessionController { public function __construct(private AuthService $auth,private BuildReviewSessionService $sessions,private NavigateReviewSessionService $navigation,private \App\Domain\Review\Repository\UserFlashcardProgressRepositoryInterface $progresses,private ReviewResponseMapper $mapper,private \App\Domain\Review\Repository\FlashcardReviewRepositoryInterface $reviews,private ApiResponseFactory $responses){} public function navigate(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,string $sessionId,string $direction):ResponseInterface{try{$user=$this->auth->currentUser($access);$now=new \DateTimeImmutable('now');$session=$this->navigation->execute($user->id,$sessionId,$direction,$now);$overdue=$this->progresses->countDueForUser($user->id,$now);return $this->responses->success($p,$this->mapper->session($session,$overdue,$overdue===0&&$this->progresses->hasUpcomingForUser($user->id,$now),$session->currentId()!==null&&$this->reviews->hasSessionReview($session->id,$session->currentId())),(string)$r->getAttribute('request_id'));}catch(\InvalidArgumentException){return $this->responses->problem($p,'VALIDATION_FAILED','Navegação inválida.',422,(string)$r->getAttribute('request_id'));}catch(\DomainException){return $this->responses->problem($p,'RESOURCE_NOT_FOUND','Sessão de revisão não encontrada.',404,(string)$r->getAttribute('request_id'));}} public function get(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,ReviewSessionKind $kind,int $limit):ResponseInterface{try{$user=$this->auth->currentUser($access);$now=new \DateTimeImmutable('now');$session=$this->sessions->execute($user->id,$kind,$limit,$now);$overdue=$this->progresses->countDueForUser($user->id,$now);return $this->responses->success($p,$this->mapper->session($session,$overdue,$overdue===0&&$this->progresses->hasUpcomingForUser($user->id,$now),$session->currentId()!==null&&$this->reviews->hasSessionReview($session->id,$session->currentId())),(string)$r->getAttribute('request_id'));}catch(\InvalidArgumentException){return $this->responses->problem($p,'VALIDATION_FAILED','Limite de revisão inválido.',422,(string)$r->getAttribute('request_id'));}catch(\DomainException $e){return $this->responses->problem($p,$kind===ReviewSessionKind::ADVANCE?'STATE_CONFLICT':'UNAUTHENTICATED',$kind===ReviewSessionKind::ADVANCE?'Existem cards vencidos para revisar.':'Credenciais invalidas ou expiradas.',$kind===ReviewSessionKind::ADVANCE?409:401,(string)$r->getAttribute('request_id'));}} }
